    if ano > today.year:
        return SlotError("veiculo_ano", "veiculo_ano_futuro", "Ano do veículo no futuro.")
    if ano < MIN_VEHICLE_YEAR:
        return SlotError("veiculo_ano", "veiculo_ano_invalido", "Ano do veículo inválido.")
    return None


