    r"|(?<![\d.,])\d{1,3}(?:\.\d{3})*,\d{2}(?![\d,])"  # 209,90 sem símbolo
)
_PERCENT = re.compile(r"\d+(?:,\d+)?\s?%")


@dataclass(frozen=True)
class OutputCheck:
    ok: bool
    offending: tuple[str, ...] = ()


def _parse(raw: str) -> Decimal:
    number = raw.replace("R$", "").strip().replace(".", "").replace(",", ".")
