def extract_money(text: str) -> list[Decimal]:
    return [_parse(m.group(0)) for m in _MONEY.finditer(text)]


def validate_output(
    text: str, last_success: QuoteResult | None, rules: PlanRules
) -> OutputCheck:
    allowed = {Decimal(p.franquia) for p in rules.plans}
