    return f"R$ {groups},{cents}"


def _join(items: list[str]) -> str:
    if len(items) <= 1:
        return "".join(items)
    return ", ".join(items[:-1]) + " e " + items[-1]


def _coverages(codes: tuple[str, ...]) -> str:
    return _join([COVERAGE_NAMES.get(c, c) for c in codes])


